import os
for k, v in os.environ.items():
    if 'MCP' in k.upper() or 'LOOP' in k.upper() or 'PORT' in k.upper() or 'URL' in k.upper():
        print(f"{k} = {v}")

import site, os
for d in site.getsitepackages():
    print("Site package:", d)
    if os.path.exists(d):
        for root, dirs, files in os.walk(d):
            for f in files:
                if 'loophole' in f.lower() or 'mcp' in f.lower():
                    print(os.path.join(root, f))

import os, glob
print("Unix sockets in /tmp:", glob.glob("/tmp/*"))
print("Unix sockets in /run:", glob.glob("/run/*"))
try:
    import psutil
    for proc in psutil.process_iter(['pid', 'name', 'cmdline']):
        print(proc.info)
except ImportError:
    print("psutil not installed")

for lib in ['trimesh', 'open3d', 'shapely', 'networkx']:
    try:
        __import__(lib)
        print(lib, "is available")
    except ImportError:
        print(lib, "is NOT available")

